# 参数1(必须): 扫描JS的目标列表
whiteListTarget := cli.Text("targets", cli.setVerboseName("白名单"),cli.setHelp("必选: 这里填写扫描白名单, 支持glob语法, 使用逗号分隔例如: example.com, cdn.example.com, *.res.example.com"))
checkWebFetchingAPI := cli.Bool("checkAPI", cli.setHelp("可选: 检测JS文件中存在的网络获取函数调用例如: fetch, XMLHttpRequest, axios等 默认开启"), cli.setDefault(true))
// checkEncryptionParam := cli.Bool("checkEnc", cli.setHelp("可选: 检测JS文件中存在的密码学加密函数调用例如: CryptoJS.AES.encrypt, forge.pki.rsa.encrypt等 默认开启"), cli.setDefault(true))
// customJSRules := cli.StringSlice("rules", cli.setHelp("可选: 这里填写自定义的JS文件扫描规则, 规则编写语法请参考SyntaxFlow语法规则"), cli.setRequired(false))
maxJSSize := cli.Int("maxSize", cli.setHelp("可选: 这个参数决定可处理的JS文件大小单位是MB 默认为2"), cli.setDefault(2))
cli.check()

# 全局变量声明
var popularJavaScriptLibraryFiles = []string{"react", "vue", "angular", "jquery", "lodash", "bootstrap", "express", "d3", "moment", "axios", "three", "socket.io", "underscore", "ember", "backbone", "redux", "meteor", "next", "nuxt", "gatsby", "svelte", "preact", "material-ui", "ant-design", "bulma", "semantic-ui", "foundation", "tailwind", "styled-components", "apollo", "graphql", "mobx", "knockout", "mithril", "aurelia", "stimulus", "alpine", "inferno", "riot", "cypress", "rxjs", "zone", "hammerjs", "yarn", "npm", "webpack", "babel", "gulp", "grunt", "browserify", "rollup", "eslint", "prettier", "stylelint", "typescript", "coffeescript", "polymer", "lit-element", "lit-html", "stencil", "dojo", "extjs", "raphael", "paper", "fabric", "konva", "anime", "mojs", "velocity", "greensock", "scrollmagic", "popmotion", "lazy", "immutable", "ramda", "bacon", "bluebird", "q", "when", "leaflet", "openlayers", "mapbox-gl", "highcharts", "amcharts", "chart", "echarts", "zrender", "dimple", "c3", "dc", "nvd3", "plottable", "sigma", "vivagraphjs", "jointjs", "cytoscape", "vis", "gojs", "fabric", "paper", "color"}
var maxSize = maxJSSize * 1024 * 1024

# 内置检测规则
xmlSF := `XMLHttpRequest().open(* as $method, * as $url,)
XMLHttpRequest...call(,* as $method, * as $url,)
`
jqPostSF := `/\$/.post(* as $obj)
			$obj.url as $url
			$obj.contentType as $contentType
			$obj.data as $data
			`
jqGetSF := `/\$/.get(* as $obj)
			$obj.url as $url
			$obj.contentType as $contentType
			$obj.data as $data`
jqBasicGet := `
/\$/.get(* as $url,)`
fetchSF := `fetch(* as $url,* as $obj)
		$obj.method as $method
		$obj.body as $body
		$obj.headers as $headers`
axiosGetSF := `axios.get(* as $url)`
axiosPostSF := `axios.post(* as $url, * as $data)`
axiosWithConfigSF := `axios(* as $config)
			$config.method as $method
			$config.url as $url
			$config.data as $data`
ajaxSF := `/\$/.ajax(* as $obj)
			$obj.type as $method 
			$obj.url as $url
			$obj.data as $data
			$obj.dataType as $dataType`
checkAPIs := map[string]string{"xmlSF": xmlSF, "jqPostSF": jqPostSF, "jqGetSF": jqGetSF, "jqBasicGet": jqBasicGet, "fetchSF": fetchSF, "axiosGetSF": axiosGetSF, "axiosPostSF": axiosPostSF, "axiosWithConfigSF": axiosWithConfigSF, "ajaxSF": ajaxSF}

# mirrorHTTPFlow 会镜像所有的流量到这里，包括 .js / .css / .jpg 这类一般会被劫持程序过滤的请求
mirrorNewWebsitePath = func(isHttps /* bool */, url /* string */, req /* []byte */, rsp /* []byte */, body /* []byte */) {
    whiteListTargets := str.Split(str.Trim(whiteListTarget, " "), ",")
    httpReq, err := str.ParseBytesToHTTPRequest(req)
    if err != nil{
        return
    }

    originHeader := httpReq.Header.Get("Origin")
    refererHeader := httpReq.Header.Get("Referer")

    // 判断是否在白名单
    inWhiteList := func(s) {
        return s != "" && str.MatchAnyOfGlob(s, whiteListTargets...)
    }

    // 只要 url、origin 或 referer 任意一个命中白名单就继续
    if !inWhiteList(str.ExtractHost(url)) && !inWhiteList(str.ExtractHost(originHeader)) && !inWhiteList(str.ExtractHost(refererHeader)) {
        log.Info(sprintf("Skip further check since not in target domain list: %s", url))
        return
    }
    log.Info("Start to check")

    isPopularJSLibrary := func(libraryFileName){
        for _, lib := range popularJavaScriptLibraryFiles {
            if str.Contains(lib, str.ToLower(libraryFileName)) {
                return true
            }
        }
        return false
    }

    res, err := str.ParseBytesToHTTPResponse(rsp)
    if err != nil{
        return
    }

    // 过滤一些不需要检测的常见JS库并确定响应体为JavaScript代码
    if str.HasSuffix(url, ".min.js") || isPopularJSLibrary(url) || !str.Contains(str.ToLower(res.Header.Get("Content-Type")), "javascript") {
        log.Info("Skip futher check since target js is popular js lib")
        return
    }

    jsCode, err := str.ExtractBodyFromHTTPResponseRaw(rsp)
    // 超长JS代码不检测
    if err != nil || len(string(jsCode)) > maxSize{
        log.Info("Skip futher check since target js is too large")
        return
    }

    jsProg, err := ssa.Parse(string(jsCode), ssa.withLanguage(ssa.Javascript))
	if err != nil {
        log.Error(sprintf("js parse failed! target js path is %s", url))
		return
	}
    endPointURL := make(map[string][]string)
    if checkWebFetchingAPI{
        log.Info("进入规则检测")
        for sfName, sfRule := range checkAPIs{
            res, err := jsProg.SyntaxFlowWithError(sfRule)
            if err == nil && res != nil{
                urls := res.GetValues("url")
                sfRes := make([]string, 0)
                for _, url := range urls{
                    if url != nil && url.GetConst() != nil && url.GetConst().GetTypeKind() ==  1 && url.String() != ""{ // StringTypeKind
                        sfRes = append(sfRes, url.String())
                    } 
                }
                if len(sfRes) > 0{
                    endPointURL[sfName] = sfRes
                }
            }
        }
    }
    if len(endPointURL) > 0{
                    risk.NewRisk(url, risk.title("从JS中检测到疑似API请求地址"),
                    risk.level("info"),
                    risk.request(req),
                    risk.response(jsCode),
                    risk.description("使用插件内置SF规则命中JS文件中的API请求路径，可以使用Irify根据命中规则，进一步审计相关网络请求函数"),
                    risk.solution(""),
                    risk.details({"APIs":endPointURL})
         )
    }

}
